entries[186683] = { ["name"] = "Formel: Ring - Werte", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (375)\nBenötigt Die Wächter der Sande\n- Respektvoll\nBenutzen: Lehrt Euch, einen Ring dauerhaft so zu verzaubern, dass er alle Werte um 4 erhöht.\nEuren eigenen Ring dauerhaft verzaubern, sodass alle Werte um 4 erhöht werden. Dadurch wird der Ring seelengebunden. Erfordert einen Gegenstand der Stufe 35 oder höher.\nVerkaufspreis:" }
entries[187048] = { ["name"] = "Muster: Große Trommeln der Wiederherstellung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (350)\nBenötigt Kurenai\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung von Großen Trommeln der Wiederherstellung.\nVerkaufspreis:\nGroße Trommeln der Wiederherstellung\nBenötigt Lederverarbeitung (350)\nBenutzen: Stellt im Verlauf von 15 Sek. 600 Gesundheit und Mana von Gruppenmitgliedern innerhalb von 40 Metern wieder her. Trommeln können in gestaltverändertem Zustand benutzt werden. Unwirksam bei Zielen der Stufe 80 oder höher. (2 Min Abklingzeit)\n50 Aufladungen\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (6), Netherdrachenschuppe (4)" }
entries[187049] = { ["name"] = "Muster: Große Trommeln des Tempos", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (345)\nBenötigt Kurenai\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung von Großen Trommeln des Tempos.\nVerkaufspreis:\nGroße Trommeln des Tempos\nBenötigt Lederverarbeitung (340)\nBenutzen: Erhöht das Bewegungstempo von Gruppenmitgliedern innerhalb von 40 Metern um 15%. Hält 30 Sek. lang an. Trommeln können in gestaltverändertem Zustand benutzt werden. (2 Min Abklingzeit)\n50 Aufladungen\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (6), Windschuppen (4)" }
