entries[206272] = { ["name"] = "Heilige Handgranate", ["text"] = "Das Ausmerzen von Stratholme\nWird beim Aufheben gebunden\nEinzigartig\nDauer: 1 tag (Realzeit)\nBenutzen: Wird auf einen verseuchten oder zombifizierten Spielercharakter als Ziel geworfen, um diesem seine menschliche Gestalt zurückzugeben.\n\nFunktioniert nicht bei Zielen oberhalb von Stufe 81.\n\"Oh, nein! Murozond hat Zombieschrecken aus der Zukunft entsandt! Ich hoffe, das hilft! - Chromie\"" }
