entries[238253] = { ["name"] = "Heldenhafte Willensstärke", ["text"] = "Herbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nBenutzen: Stählt die Konzentration des Zaubernden, um den Mächten des Zwielichts zu widerstehen. Transportiert den Zaubernden bis zu 5 Sek. lang aus dem Zwielichtreich hinaus, jedoch kann er weder angreifen noch Zauber wirken oder sich bewegen, während er sich konzentriert. (5 Sek. Abklingzeit)\n50 Aufladungen\n\"Ein mächtiges Artefakt, das von einem noch mächtigeren Zwerg geborgen wurde.\"" }
